/* Elements
0  O
1  H
2  C
3  N
4  Ar
*/

// Species
#define H2_ID 0
#define H_ID 1
#define O_ID 2
#define O2_ID 3
#define OH_ID 4
#define H2O_ID 5
#define HO2_ID 6
#define CH2_ID 7
#define CH2_S_ID 8
#define CH3_ID 9
#define CH4_ID 10
#define CO_ID 11
#define CO2_ID 12
#define HCO_ID 13
#define CH2O_ID 14
#define CH3O_ID 15
#define C2H4_ID 16
#define C2H5_ID 17
#define C2H6_ID 18
#define N2_ID 19
#define AR_ID 20

#define NUM_GAS_ELEMENTS 5   // Elements in the homogeneous phase
#define NUM_GAS_SPECIES 21   // Species in the homogeneous phase
#define NUM_GAS_REACTIONS 84 // Reactions in the homogeneous phase

#define SITE_DENSITY 0.000000E+00 // mol/cm^2

#define NUM_SURFACE_ELEMENTS 0  // Additional elements in heterogeneous phase
#define NUM_SURFACE_SPECIES 0   // Species in the heterogeneous phase
#define NUM_SURFACE_REACTIONS 0 // Reactions in the heterogeneous phase

#define NUM_ELEMENTS (NUM_GAS_ELEMENTS + NUM_SURFACE_ELEMENTS)
#define NUM_SPECIES (NUM_GAS_SPECIES + NUM_SURFACE_SPECIES)
#define NUM_REACTIONS (NUM_GAS_REACTIONS + NUM_SURFACE_REACTIONS)

#define NUM_IONS 0

#define NUM_FIT 4

