              (+2.500000000000000e+00 + 3.526664095000000e-13 * T -
               6.653065466666667e-16 * T2 + 5.752040800000000e-19 * T3 -
               1.855464664000000e-22 * T4 + 2.547365990000000e+04 * invT) *
              0.9920634920634921;
    // species 2: O
    result += y[2] *
              (+3.168267100000000e+00 - 1.639659420000000e-03 * T +
               2.214354653333333e-06 * T2 - 1.532016560000000e-09 * T3 +
               4.225319420000000e-13 * T4 + 2.912225920000000e+04 * invT) *
              0.0625039064941559;
    // species 3: O2
