  J[67] -= dqdci; // dwdot[H]/d[O2]
  J[69] -= dqdci; // dwdot[O2]/d[O2]
  J[72] += dqdci; // dwdot[HO2]/d[O2]
  // d()/d[HO2]
  dqdci = -k_r * sc[20];
  J[133] -= dqdci; // dwdot[H]/d[HO2]
  J[135] -= dqdci; // dwdot[O2]/d[HO2]
  J[138] += dqdci; // dwdot[HO2]/d[HO2]
  // d()/d[AR]
  dqdci = +k_f * sc[1] * sc[3] - k_r * sc[6];
  J[441] -= dqdci; // dwdot[H]/d[AR]
  J[443] -= dqdci; // dwdot[O2]/d[AR]
  J[446] += dqdci; // dwdot[HO2]/d[AR]
  // d()/dT
  J[463] -= dqdT; // dwdot[H]/dT
  J[465] -= dqdT; // dwdot[O2]/dT
  J[468] += dqdT; // dwdot[HO2]/dT

  // reaction 22: 2 H + M <=> H2 + M
  // a third-body and non-pressure-fall-off reaction
  // 3-body correction factor
  alpha = mixture + (0 - 1) * sc[0] + (0 - 1) * sc[5] + sc[10] +
          (0 - 1) * sc[12] + (3 - 1) * sc[18] + (0.63 - 1) * sc[20];
  // forward
  phi_f = (sc[1] * sc[1]);
  k_f = 1000000 * exp(-1 * logT);
  dlnkfdT = -1 * invT;
  // reverse
  phi_r = sc[0];
  Kc = refCinv * (kc_fast ? (ge[0] * inv_ge[1] * inv_ge[1])
                          : exp(-g_RT[0] + 2.000000 * g_RT[1]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(2.000000 * h_RT[1]) + (h_RT[0]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q_nocor = k_f * phi_f - k_r * phi_r;
  q = alpha * q_nocor;
  dqdT = alpha * (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[0] += q;     // H2
  wdot[1] -= 2 * q; // H
  // for convenience
  k_f *= alpha;
  k_r *= alpha;
  dqdc[0] = -k_r;
  dqdc[1] = q_nocor + k_f * 2.000000 * sc[1];
  dqdc[2] = q_nocor;
  dqdc[3] = q_nocor;
  dqdc[4] = q_nocor;
  dqdc[5] = 0.0;
  dqdc[6] = q_nocor;
  dqdc[7] = q_nocor;
  dqdc[8] = q_nocor;
  dqdc[9] = q_nocor;
  dqdc[10] = 2 * q_nocor;
  dqdc[11] = q_nocor;
  dqdc[12] = 0.0;
  dqdc[13] = q_nocor;
  dqdc[14] = q_nocor;
  dqdc[15] = q_nocor;
  dqdc[16] = q_nocor;
  dqdc[17] = q_nocor;
  dqdc[18] = 3 * q_nocor;
  dqdc[19] = q_nocor;
  dqdc[20] = 0.63 * q_nocor;
  for (int k = 0; k < 21; k++) {
    J[22 * k + 0] += dqdc[k];
    J[22 * k + 1] += -2 * dqdc[k];
  }
  J[462] += dqdT;      // dwdot[H2]/dT
  J[463] += -2 * dqdT; // dwdot[H]/dT

  // reaction 23: 2 H + H2 <=> H2 + H2
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[0] * (sc[1] * sc[1]);
  k_f = 90000 * exp(-0.6 * logT);
  dlnkfdT = -0.6 * invT;
  // reverse
  phi_r = (sc[0] * sc[0]);
  Kc = refCinv * (kc_fast ? (ge[0] * inv_ge[1] * inv_ge[1])
                          : exp(-g_RT[0] + 2.000000 * g_RT[1]));
