  dqdc[0] = 0.73 * q_nocor;
  dqdc[1] = q_nocor + k_f * sc[4];
  dqdc[2] = q_nocor;
  dqdc[3] = q_nocor;
  dqdc[4] = q_nocor + k_f * sc[1];
