  wdot[1] += q;  // H
  wdot[11] += q; // CO
  wdot[13] -= q; // HCO
  // d()/d[H]
  dqdci = -k_r * sc[5] * sc[11];
  J[23] += dqdci; // dwdot[H]/d[H]
