  J[466] += dqdT; // dwdot[OH]/dT
  J[468] -= dqdT; // dwdot[HO2]/dT

  // reaction 3: CH2 + O <=> H + HCO
  // a non-third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[2] * sc[7];
  k_f = 80000000;
