  // reverse
  phi_r = sc[14];
  Kc = refCinv * (kc_fast ? (inv_ge[0] * ge[14] * inv_ge[11])
                          : exp(g_RT[0] + g_RT[11] - g_RT[14]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(h_RT[0] + h_RT[11]) + (h_RT[14]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
