           (28.054000 * 28.054000 * 50.410000);
  bi[16] = 0.08664 * Rcst * Tci[16] / (28.054000 * 50.410000);
  acentric_i[16] = 0.087000;

  // species 17: C2H5
  Tci[17] = 1.316 * EPS[17];
