  bi[17] = 0.855 * avogadro * 1e-24 * SIG[17] * SIG[17] * SIG[17] / (wt[17]);
  acentric_i[17] = 0.0;

  // species 18: C2H6
  // Imported from NIST
  Tci[18] = 305.320000;
  ai[18] = 1e6 * 0.42748 * Rcst * Rcst * Tci[18] * Tci[18] /
           (30.070120 * 30.070120 * 48.720000);
  bi[18] = 0.08664 * Rcst * Tci[18] / (30.070120 * 48.720000);
  acentric_i[18] = 0.099000;

  // species 19: N2
  // Imported from NIST
  Tci[19] = 126.192000;
  ai[19] = 1e6 * 0.42748 * Rcst * Rcst * Tci[19] * Tci[19] /
           (28.013400 * 28.013400 * 33.958000);
  bi[19] = 0.08664 * Rcst * Tci[19] / (28.013400 * 33.958000);
  acentric_i[19] = 0.037200;

  // species 20: AR
